import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/21-陌生情景测试.md","filePath":"books/attached/21-陌生情景测试.md","lastUpdated":1794298621000}'),l={name:"books/attached/21-陌生情景测试.md"};function n(d,a,c,p,_,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"陌生情景测试",tabindex:"-1"},[s("陌生情景测试 "),e("a",{class:"header-anchor",href:"#陌生情景测试","aria-label":'Permalink to "陌生情景测试"'},"​")],-1),e("p",null,"萨拉（Sarah）与她一周岁大的女儿金米（Kimmy），走进了一件摆满玩具的房间。一位很友善的年轻研究助理已经等在那里了，跟她们简单交谈了几句。金米立刻开始了对这片玩具天堂的探索，她在玩具堆里徜徉，把玩具们丢来丢去，试着探索这些玩具是否会发出声响，是不是会自己跑动或是亮起灯来。与此同时，又时不时地瞟一眼她妈妈。",-1),e("p",null,"接着，金米的妈妈接到安排，需要离开房间，于是她很快起身走了出去。金米意识到妈妈走出去，立马开始坐立不安了。她飞一般地竭力向房门爬过去，并且开始抽泣。她大声叫着妈妈，并且捶着房门。研究助手试着用一大盒彩色积木来吸引金米的注意，但这只让金米的情绪变本加厉，她直接把一盒积木当着研究助理的面扔了出去。",-1),e("p",null,"不一会儿，她妈妈回到了房间，金米立马目不转睛地向妈妈冲过去，还挥舞着双臂以求拥抱。萨拉也伸手抱住女儿，并且安抚了孩子。当金米的情绪稳定下来以后，她又对玩具恢复了兴趣，重新开始专注地玩耍。",-1),e("p",null,"萨拉和金米参加的这个实验，大概是依恋理论研究领域中最为重要的一项研究了，它就是玛丽·安斯沃思所做的著名的陌生情景测试，不过这里提到的只是测验的一个简述。安斯沃思被一个现象深深地吸引了：孩子的探索进程，或者说学习与玩耍的能力，是完全会被母亲的在场与缺席左右的。母亲在场时，孩子会从容地探索和求知；而母亲离开后，这种求知也会被扼杀。",-1),e("p",null,"安斯沃思还发现，依恋对象的存在，足以促使孩子到一个预先未知的环境，并且带着自信去探索未知领域。而依恋对象的存在，也就产生了所谓的“安全基地”（secure base）。安全基地其实是我们的一种认识，我们确定有人会在身后支持我们，而且我们百分之百可以在有所需要的时候依靠这个人。“安全基地”的存在，是孩子们探索、发展与学习的先决条件。",-1)])])}const h=t(l,[["render",n]]);export{u as __pageData,h as default};
